### Python

```python
# -*- coding: utf-8 -*-
# 题意实现函数放在外部；主函数只负责输入输出（ACM风格）

from typing import List, Tuple

def calc_min_total_time(n: int, x: int, m: int,
                        a: List[int], q: List[int], r: List[int]) -> int:
    """计算最小总观看时长"""
    # 单位时长系数为 min(a_i, x)
    coeff = [min(a[i], x) for i in range(n)]
    base = 0  # 先分配下界
    caps = []
    for i in range(n):
        base += q[i] * coeff[i]
        caps.append((coeff[i], r[i] - q[i]))  # (系数, 还能加的次数)
    left = m - sum(q)
    # 按系数从小到大贪心
    caps.sort(key=lambda t: t[0])
    res = base
    for c, cap in caps:
        if left <= 0:
            break
        add = min(left, cap)
        res += add * c
        left -= add
    return res

def calc_max_total_time(n: int, x: int, m: int,
                        a: List[int], q: List[int], r: List[int]) -> int:
    """计算最大总观看时长"""
    coeff = [a[i] for i in range(n)]  # 单位时长系数为 a_i
    base = 0
    caps = []
    for i in range(n):
        base += q[i] * coeff[i]
        caps.append((coeff[i], r[i] - q[i]))
    left = m - sum(q)
    # 按系数从大到小贪心
    caps.sort(key=lambda t: -t[0])
    res = base
    for c, cap in caps:
        if left <= 0:
            break
        add = min(left, cap)
        res += add * c
        left -= add
    return res

def main():
    # 输入：n x m
    n, x, m = map(int, input().split())
    a = list(map(int, input().split()))
    q = list(map(int, input().split()))
    r = list(map(int, input().split()))
    L = calc_min_total_time(n, x, m, a, q, r)
    R = calc_max_total_time(n, x, m, a, q, r)
    print(L, R)

if __name__ == "__main__":
    main()
```

