        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) r[i] = Long.parseLong(st.nextToken());

        long L = calcMin(n, x, m, a, q, r);
        long R = calcMax(n, x, m, a, q, r);
        System.out.println(L + " " + R);
    }
